with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , PACKAGE_RATES as PACKAGE_RATE
        , TARIFF_FROM_DATE as EFFECTIVE_DATE
        , TARIFF_TO_DATE as EXPIRY_DATE
        , PP_DISCOUNT12 as DISCOUNT_PERCENTAGE
        , PP_DISC_SERVICES12 as SERVICE_DESCRIPTION
        , cast(null as varchar) as ROOM_RENT_CAP
        , 'BJAZ_HM_HOSPITAL_MASTER_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master_extn') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , cast(null as varchar) as PACKAGE_RATE
        , cast(null as varchar) as EFFECTIVE_DATE
        , cast(null as varchar) as EXPIRY_DATE
        , cast(null as varchar) as DISCOUNT_PERCENTAGE
        , cast(null as varchar) as SERVICE_DESCRIPTION
        , STEPDWNRMRENT as ROOM_RENT_CAP
        , 'BJAZ_HM_HOSP_MASTER_EXTN1' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hosp_master_extn1') }}
    where (nullif(trim(HOSID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PACKAGE_RATE end) as PACKAGE_RATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EFFECTIVE_DATE end) as EFFECTIVE_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EXPIRY_DATE end) as EXPIRY_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISCOUNT_PERCENTAGE end) as DISCOUNT_PERCENTAGE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SERVICE_DESCRIPTION end) as SERVICE_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ROOM_RENT_CAP end) as ROOM_RENT_CAP,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when PACKAGE_RATE is not null or EFFECTIVE_DATE is not null or EXPIRY_DATE is not null or DISCOUNT_PERCENTAGE is not null or SERVICE_DESCRIPTION is not null or ROOM_RENT_CAP is not null
                     then md5(upper(coalesce(cast(PACKAGE_RATE as varchar), '') || '|' || coalesce(cast(EFFECTIVE_DATE as varchar), '') || '|' || coalesce(cast(EXPIRY_DATE as varchar), '') || '|' || coalesce(cast(DISCOUNT_PERCENTAGE as varchar), '') || '|' || coalesce(cast(SERVICE_DESCRIPTION as varchar), '') || '|' || coalesce(cast(ROOM_RENT_CAP as varchar), '')))
                end as SAT_PROVIDER_TARIFF_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PROVIDER_TARIFF_HASHDIFF is not null
